do $$begin
 if exists(select 1 from requested_matriz_tasks where coalesce(work_branch(item->>'employeeId','2026-11-07'),(select v->>'branch' from app_state s cross join lateral jsonb_array_elements(s.value)v where s.key='xoxo.collaborators' and v->>'id'=item->>'employeeId' limit 1),'')<>'Matriz') then raise exception 'Una persona no está asignada a Matriz';end if;
end $$;
insert into daily_task_records(record_id,employee_number,branch,record_date,payload,updated_by) select item->>'id',item->>'employeeId','Matriz','2026-11-07',item||jsonb_build_object('assignedAt',now()),(select user_id from profiles where employee_number='003' and active) from requested_matriz_tasks on conflict(record_id) do nothing;
drop table requested_matriz_tasks;
commit;
select employee_number as colaborador,count(*) as tareas,min(record_date) as fecha,bool_and(branch='Matriz' and payload->>'priority'='Alta') as prioridad_matriz from daily_task_records where record_id like 'prioridad-matriz-2026-11-07-%' group by employee_number order by employee_number;
